    "name": "Editor/MargoMesh.Unity.Editor.asmdef",
    "text": "{\n  \"name\": \"MargoMesh.Unity.Editor\",\n  \"rootNamespace\": \"MargoMesh.Unity.Editor\",\n  \"references\": [\"MargoMesh.Unity\", \"glTFast\", \"Unity.Collections\"],\n  \"includePlatforms\": [\"Editor\"],\n  \"autoReferenced\": true\n}\n"
